    if (rawKey === '__proto__') {
      warnings.push(ERROR_CODES.BAD_DATA);
      continue;
    }
    const entry = workspaces[rawKey];
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
      warnings.push(ERROR_CODES.BAD_DATA);
      continue;
    }
