  if (!workspacesReady || !Array.isArray(storedIds) || !Array.isArray(validIds)) return [];
  const valid = new Set(
    validIds
      .filter(function (id) {
        return id !== undefined && id !== null;
      })
      .map(function (id) {
        return String(id);
      })
  );
  return storedIds.filter(function (id) {
    return !valid.has(String(id));
  });
